options=read('/input/options')
result=[]
for c in combinations(options,3):
  sel=list(c)
  sel_ids=[x['id'] for x in sel]
  workers=[x['worker'] for x in sel]
  jobs=[x['job'] for x in sel]
  # Check unique workers and jobs without using set
  unique_workers=[]
  unique_jobs=[]
  for w in workers:
    if w not in unique_workers:
      unique_workers=unique_workers+[w]
  for j in jobs:
    if j not in unique_jobs:
      unique_jobs=unique_jobs+[j]
  if len(unique_workers)!=3: continue
  if len(unique_jobs)!=3: continue
  # Check coverage of jobs
  job_cover=['j0','j1','j2']
  job_cover_found=True
  for jc in job_cover:
    found=False
    for j in jobs:
      if j==jc:
        found=True
        break
    if not found:
      job_cover_found=False
      break
  if not job_cover_found: continue
  # Check requires
  valid_requires=True
  for x in sel:
    for r in x['requires']:
      found_r=False
      for sid in sel_ids:
        if sid==r:
          found_r=True
          break
      if not found_r:
        valid_requires=False
        break
    if not valid_requires:
      break
  if not valid_requires: continue
  # Check conflicts
  conflict_found=False
  for x in sel:
    for c_id in x['conflicts']:
      for sid in sel_ids:
        if sid==c_id:
          conflict_found=True
          break
      if conflict_found:
        break
    if conflict_found:
      break
  if conflict_found: continue
  # Check count
  if len(sel)!=3: continue
  result=sel_ids
  break
